// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockERC20 sGlp;
    MockERC20 usdc;
    MockRewardRouter router;
    MockJuniorVault jv;
    address keeper = address(0xA11CE);

    function setUp() public {
        c = new DnGmxBatchingManager();
        sGlp = new MockERC20();
        usdc = new MockERC20();
        router = new MockRewardRouter();
        jv = new MockJuniorVault();
        MockVault mv = new MockVault();
        MockGlpManager gm = new MockGlpManager(address(mv));
        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(router)), IGlpManager(address(gm)), address(jv), keeper);
    }

    function testFuzz_property(uint256 usdcAmount, uint256 glpStaked) public {
        usdcAmount = bound(usdcAmount, 1, 1e24);
        glpStaked = bound(glpStaked, 1, type(uint128).max);
        router.setGlpOut(glpStaked);

        // only the junior vault may call depositToken
        vm.prank(address(jv));
        c.depositToken(address(usdc), usdcAmount, 0);

        // the tracked GLP balance reflects exactly what was staked
        require(c.dnGmxJuniorVaultGlpBalance() == glpStaked, "setup");

        // pass the cooldown of executeBatchDeposit, then let the keeper batch-deposit
        vm.warp(block.timestamp + 16 minutes);
        vm.prank(keeper);
        c.executeBatchDeposit();

        // GENERAL RULE: after executeBatchDeposit, everything tracked has been
        // handed to the junior vault exactly once and the tracker is cleared to zero.
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == 0);
    }
}

